"""Mirror notes for OneDrive presentations (slide extraction lives in ``core.extract``)."""

from __future__ import annotations

from lifeos.core.extract.pptx import Slide, extract, slides_markdown
from lifeos.core.extract.text import ExtractError, dump_front, front_matter, link, mark_deleted

NOTICE = (
    "> Mirror of [{title}]({url}) in OneDrive, generated by LifeOS. Edit the presentation"
    " in PowerPoint; changes here are overwritten on the next sync."
)


def render(meta: dict, slides: list[Slide]) -> str:
    front = {
        "type": "presentation",
        "source": "onedrive",
        "title": meta["title"],
        "url": meta["url"],
        "onedrive_path": meta["path"],
        "drive_item_id": meta["id"],
        "modified": meta["modified"],
        "slides": len(slides),
        "mirror": True,
    }
    notice = NOTICE.format(title=meta["title"].replace("]", "\\]"), url=link(meta["url"]))
    body = slides_markdown(slides) if slides else ""
    return f"{dump_front(front)}\n# {meta['title']}\n\n{notice}\n\n{body}".rstrip() + "\n"


__all__ = ["ExtractError", "extract", "front_matter", "mark_deleted", "render"]
